 obj={'role':role,'case_id':role+'-SAME-CONTENT-01','source':{'path':d['source_path'],'sha256':d['sha256']},'xml':section,'table_xpath':t['xpath'],'table_locator':t['evidence'],'logical_rows_zero_based':rows,'cells':[{'locator':c['evidence'],'address':c['address'],'span':next(x['attributes'] for x in c['properties'] if x['tag']=='cellSpan'),'text_verbatim':c['text']} for c in cells],'purpose':purpose,'source_issues':issues,'reproduction_notice':'참고 원문 재현 비교용 사본(새 사업 수행·승인·서명 증거 아님)','status':'selected_raw_content_only_input_mapping_pending','actual_quality_score_percent':None}
 # Exact referenced image binary identities within the selected table.
 with zipfile.ZipFile(d['source_path']) as z:
  root=E.fromstring(z.read(section));table=root.xpath(t['xpath'],namespaces=NS)[0];opf=E.fromstring(z.read('Contents/content.hpf'));items={x.get('id'):x.get('href') for x in opf.xpath('//*[local-name()="manifest"]/*[local-name()="item"]')};pics=[]
  for pic in table.findall('.//hp:pic',NS):
   img=pic.find('.//{http://www.hancom.co.kr/hwpml/2011/core}img');iid=img.get('binaryItemIDRef');href=items[iid];href=href if href in z.namelist() else 'Contents/'+href
   pics.append({'picture_xpath':root.getroottree().getpath(pic),'binary_item_id':iid,'zip_member':href,'binary_sha256':sha256(z.read(href)).hexdigest(),'evidence_status':'reference_image_for_reproduction_only_not_actual_new_execution'})
  obj['figures']=pics
 selections.append(obj)
